import java.util.*;
import java.io.*;

public class Main {
    static long[] solve(long[] charge, int[][] queries) {
        // Write your solution here
        return new long[queries.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] charge = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            charge[i] = (long) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            queries[i][0] = (int) in.nval;
            in.nextToken();
            queries[i][1] = (int) in.nval;
        }
        long[] ans = solve(charge, queries);
        StringBuilder sb = new StringBuilder();
        for (long x : ans) sb.append(x).append('\n');
        System.out.print(sb);
    }
}

