def gen(rng):
    def valid(d):
        n = len(d)
        for i in range(n):
            ds = sorted(abs(d[i] - d[j]) for j in range(n) if j != i)
            if len(ds) > 1 and ds[0] == ds[1]:
                return False
        return True
    def fmt(d, qs):
        return f"{len(d)}\n" + ' '.join(map(str, d)) + f"\n{len(qs)}\n" + '\n'.join(f'{s} {e}' for s, e in qs)
    def all_pairs(n):
        return [(s, e) for s in range(n) for e in range(n)]
    tests = [
        fmt([1, 4, 6], all_pairs(3)),
        fmt([7, 20], all_pairs(2)),
        fmt([1, 3, 10, 12], [(0, 3), (3, 0), (2, 0), (0, 2), (1, 1)]),
        fmt([5, 5], all_pairs(2)),
        fmt([1, 2, 10, 10], all_pairs(4)),
        fmt([1, 10**9], [(0, 1), (1, 0)]),
        fmt([1, 2, 4, 8, 16, 32], all_pairs(6)),
    ]
    def small_valid(n, hi):
        for _ in range(500):
            d = [rng.randint(1, hi) for _ in range(n)]
            if valid(d):
                return d
        return sorted(rng.sample(range(1, 10**6), n))
    def strict(n, maxgap):
        gaps = [rng.randint(1, maxgap) for _ in range(n - 1)]
        for i in range(1, n - 1):
            while gaps[i] == gaps[i - 1]:
                gaps[i] += 1
        v = [rng.randint(1, 1000)]
